from collections import Counter

def histogram(test):
    """A
    a string representing a space-separated lowercase letters, return a dictionary of the letter with the most repetition and containing the corresponding count.

    If several letters have the same occurrence, return all of them.


    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """

    if not test:
        return {}

    letter_counts = Counter(test.split())
    max_count = max(letter_counts.values())

    most_repeated_letters = {letter: count for letter,  count in letter_counts.items() if count == max_count}


    return most_repeated_letters

# Example usage:
print(histogram('a b c'))  # Output: {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))  # Output: {'a': 2, 'b': 2}
print(histogram('a b c a b'))  # Output: {'a': 2, 'b': 2}
print(histogram('b b b b a'))  # Output: {'b': 4}
print(histogram(''))  # Output: {}
