def tri(n):
    """Generate the first n+1 numbers of the Tribonacci sequence."""


    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    elif n == 0:
        return [3]
    elif n == 1:
        return [3, 1]
    else:
        fib_sequence = [3]  # Initialize the sequence with the Tribonacci number at position 1
        for i in range(2, n + 1):
            if i % 2 == 0:
                fib_sequence.append(i / 2)

            else:
                fib_sequence.append(fib_sequence[i - 1] + fib_sequence[i - 2] + fib_sequence[i + 1])

        return fib_sequence

# Example usage:
print(tri(3))  # Output: [1, 3, 2, 8]
